field.eval:
[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'orders', 'config': {'args': {
    'model': 'purchase.order',
    'domain': [['state', 'in', ['draft', 'sent']]],
    'fields': ['name', 'partner_id', 'amount_total', 'date_order', 'state'],
    'limit': 15, 'order': 'date_order asc'}}},
  {'type': 'agent', 'resultVariable': 'triage', 'config': {'instruction': 'Triage these open purchase orders in ${orders}: vendor, amount, age and state. For each, say confirm, chase the vendor, or cancel.'}},
  {'type': 'output', 'config': {'value': '${triage}'}}
]

[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'deals', 'config': {'args': {
    'model': 'crm.lead',
    'domain': [['type', '=', 'opportunity']],
    'fields': ['name', 'partner_id', 'expected_revenue', 'probability', 'stage_id'],
    'limit': 10, 'order': 'expected_revenue desc'}}},
  {'type': 'agent', 'resultVariable': 'ranking', 'config': {'instruction': 'Rank these open deals in ${deals} by expected value times probability: name, amount, stage, and the one action that moves each forward.'}},
  {'type': 'output', 'config': {'value': '${ranking}'}}
]

[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'orders', 'config': {'args': {
    'model': 'mrp.production',
    'domain': [['state', 'not in', ['done', 'cancel']]],
    'fields': ['name', 'product_id', 'product_qty', 'date_deadline', 'state'],
    'limit': 15, 'order': 'date_deadline asc'}}},
  {'type': 'agent', 'resultVariable': 'status', 'config': {'instruction': 'Report these open manufacturing orders in ${orders}: order, product, quantity, deadline and state. Flag anything past deadline.'}},
  {'type': 'output', 'config': {'value': '${status}'}}
]

[
  {'type': 'start', 'config': {'variables': [{'name': 'since', 'type': 'required', 'description': 'Hired on or after this date (YYYY-MM-DD)'}]}},
  {'type': 'search', 'resultVariable': 'hires', 'config': {'args': {
    'model': 'hr.employee',
    'domain': [['create_date', '>=', '${since}']],
    'fields': ['name', 'job_title', 'department_id', 'work_email'],
    'limit': 20, 'order': 'create_date desc'}}},
  {'type': 'agent', 'resultVariable': 'welcome', 'config': {'instruction': 'List these new hires in ${hires}: name, role, department, contact. Suggest one onboarding check per person.'}},
  {'type': 'output', 'config': {'value': '${welcome}'}}
]

[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'pickings', 'config': {'args': {
    'model': 'stock.picking',
    'domain': [['picking_type_id.code', '=', 'incoming'], ['state', 'in', ['confirmed', 'assigned']]],
    'fields': ['name', 'partner_id', 'scheduled_date', 'state'],
    'limit': 15, 'order': 'scheduled_date asc'}}},
  {'type': 'agent', 'resultVariable': 'docks', 'config': {'instruction': 'List these incoming shipments in ${pickings}: reference, vendor, scheduled date and state. Flag anything past scheduled date.'}},
  {'type': 'output', 'config': {'value': '${docks}'}}
]

[
  {'type': 'start', 'config': {'variables': []}},
  {'type': 'search', 'resultVariable': 'bills', 'config': {'args': {
    'model': 'account.move',
    'domain': [['move_type', '=', 'in_invoice']],
    'fields': ['name', 'partner_id', 'amount_total', 'state', 'invoice_date'],
    'limit': 10, 'order': 'invoice_date desc'}}},
  {'type': 'agent', 'resultVariable': 'review', 'config': {'instruction': 'Review these recent vendor bills in ${bills}: vendor, amount, state. Flag any draft older than it should be.'}},
  {'type': 'output', 'config': {'value': '${review}'}}
]
